package merkle

import (
	"crypto/sha256"
)

// hashLeaf hashes a single leaf value with a domain-separation prefix.
func hashLeaf(data []byte) []byte {
	buf := make([]byte, 0, len(data)+1)
	buf = append(buf, 0x00)
	buf = append(buf, data...)
	sum := sha256.Sum256(buf)
	return sum[:]
}

// hashNode hashes two child hashes together with a domain-separation prefix.
func hashNode(left []byte, right []byte) []byte {
	buf := make([]byte, 0, len(left)+len(right)+1)
	buf = append(buf, 0x01)
	buf = append(buf, left...)
	buf = append(buf, right...)
	sum := sha256.Sum256(buf)
	return sum[:]
}

// Root computes the Merkle root of a list of leaves.
// Odd nodes at any level are promoted (duplicated is NOT used, to avoid
// second-preimage style ambiguity; instead the lone node carries forward).
func Root(leaves [][]byte) []byte {
	if len(leaves) == 0 {
		panic("merkle: empty leaves")
	}
	level := make([][]byte, len(leaves))
	for i, l := range leaves {
		level[i] = hashLeaf(l)
	}
	for len(level) > 1 {
		next := make([][]byte, 0, (len(level)+1)/2)
		for i := 0; i < len(level); i += 2 {
			if i+1 < len(level) {
				next = append(next, hashNode(level[i], level[i+1]))
			} else {
				next = append(next, level[i])
			}
		}
		level = next
	}
	return level[0]
}

// Proof is a single step in a Merkle inclusion proof.
type Proof struct {
	Hash    []byte
	IsRight bool // true if this hash is the right sibling
}

// GenerateProof builds an inclusion proof for the leaf at index `idx`.
func GenerateProof(leaves [][]byte, idx int) []Proof {
	if idx < 0 || idx >= len(leaves) {
		panic("merkle: index out of range")
	}
	level := make([][]byte, len(leaves))
	for i, l := range leaves {
		level[i] = hashLeaf(l)
	}

	proof := []Proof{}
	pos := idx
	for len(level) > 1 {
		next := make([][]byte, 0, (len(level)+1)/2)
		for i := 0; i < len(level); i += 2 {
			if i+1 < len(level) {
				if i == pos || i+1 == pos {
					if i == pos {
						proof = append(proof, Proof{Hash: level[i+1], IsRight: true})
					} else {
						proof = append(proof, Proof{Hash: level[i], IsRight: false})
					}
				}
				next = append(next, hashNode(level[i], level[i+1]))
			} else {
				next = append(next, level[i])
			}
		}
		pos = pos / 2
		level = next
	}
	return proof
}

// VerifyProof checks that a leaf, combined with its proof, produces the given root.
func VerifyProof(leaf []byte, proof []Proof, root []byte) bool {
	h := hashLeaf(leaf)
	for _, p := range proof {
		if p.IsRight {
			h = hashNode(h, p.Hash)
		} else {
			h = hashNode(p.Hash, h)
		}
	}
	if len(h) != len(root) {
		return false
	}
	for i := range h {
		if h[i] != root[i] {
			return false
		}
	}
	return true
}

package commitreveal

import (
	"crypto/sha256"
)

// ComputeCommitment hashes a secret value together with a salt/nonce,
// producing a commitment that hides the value until revealed.
// commitment = sha256(0x00 || salt || value)
func ComputeCommitment(salt []byte, value []byte) []byte {
	buf := make([]byte, 0, len(salt)+len(value)+1)
	buf = append(buf, 0x00)
	buf = append(buf, salt...)
	buf = append(buf, value...)
	sum := sha256.Sum256(buf)
	return sum[:]
}

// VerifyReveal checks that a revealed (salt, value) pair matches a
// previously stored commitment.
func VerifyReveal(commitment []byte, salt []byte, value []byte) bool {
	computed := ComputeCommitment(salt, value)
	if len(computed) != len(commitment) {
		return false
	}
	for i := range computed {
		if computed[i] != commitment[i] {
			return false
		}
	}
	return true
}

// Phase represents the lifecycle stage of a commit-reveal round.
type Phase int

const (
	PhaseCommit Phase = iota
	PhaseReveal
	PhaseClosed
)

func (p Phase) String() string {
	switch p {
	case PhaseCommit:
		return "commit"
	case PhaseReveal:
		return "reveal"
	case PhaseClosed:
		return "closed"
	default:
		return "unknown"
	}
}

// Round tracks the block-height boundaries for a commit-reveal cycle.
// Consumers embed this in their own realm state and drive phase transitions
// using the chain height they read via chain/runtime.
type Round struct {
	CommitEndsAt int64
	RevealEndsAt int64
}

// NewRound creates a round starting at `now`, with the given commit and
// reveal window lengths (in blocks).
func NewRound(now int64, commitBlocks int64, revealBlocks int64) Round {
	if commitBlocks <= 0 || revealBlocks <= 0 {
		panic("commitreveal: window lengths must be positive")
	}
	return Round{
		CommitEndsAt: now + commitBlocks,
		RevealEndsAt: now + commitBlocks + revealBlocks,
	}
}

// PhaseAt returns which phase the round is in at the given height.
func (r Round) PhaseAt(height int64) Phase {
	switch {
	case height <= r.CommitEndsAt:
		return PhaseCommit
	case height <= r.RevealEndsAt:
		return PhaseReveal
	default:
		return PhaseClosed
	}
}

package raffle

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"crypto/sha256"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"

	"gno.land/p/g16m0r7rm7fv5hx0ekr7gvx8g4fr7eu08nzhk6gt/commitreveal"
)

type RaffleStatus int

const (
	StatusOpen RaffleStatus = iota
	StatusCommitted
	StatusRevealed
	StatusClosed
)

func (s RaffleStatus) String() string {
	switch s {
	case StatusOpen:
		return "open"
	case StatusCommitted:
		return "committed"
	case StatusRevealed:
		return "revealed"
	case StatusClosed:
		return "closed"
	default:
		return "unknown"
	}
}

type Entry struct {
	Index  int64
	Player address
}

var (
	admin        address
	ticketPrice  int64
	entries      []Entry
	entriesByIdx *avl.Tree // index string -> *Entry (for quick winner lookup)
	status       RaffleStatus
	commitment   []byte
	winner       address
	pot          int64
	round        commitreveal.Round
)

func init() {
	admin = address("g16m0r7rm7fv5hx0ekr7gvx8g4fr7eu08nzhk6gt")
	ticketPrice = 1000000 // 1 gnot per ticket
	entries = []Entry{}
	entriesByIdx = avl.NewTree()
	status = StatusOpen
}

func assertUserCall(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("raffle: must be a direct user call")
	}
	return cur.Previous().Address()
}

// Enter buys a ticket for the current raffle round.
func Enter(cur realm) {
	caller := assertUserCall(cur)
	if status != StatusOpen {
		panic("raffle: entries are closed for this round")
	}
	sent := unsafe.OriginSend()
	amount := sent.AmountOf("ugnot")
	if amount != ticketPrice {
		panic("raffle: must send exact ticket price")
	}

	idx := int64(len(entries))
	e := Entry{Index: idx, Player: caller}
	entries = append(entries, e)
	entriesByIdx.Set(ufmt.Sprintf("%020d", idx), &e)
	pot += amount
}

// CommitWinnerSeed lets admin commit to a random seed before revealing the winner.
// This prevents the admin from picking a favorable seed after seeing entries.
func CommitWinnerSeed(cur realm, commitHash []byte) {
	caller := assertUserCall(cur)
	if caller != admin {
		panic("raffle: admin only")
	}
	if status != StatusOpen {
		panic("raffle: raffle not open")
	}
	if len(entries) == 0 {
		panic("raffle: no entries yet")
	}
	commitment = commitHash
	status = StatusCommitted
	round = commitreveal.NewRound(runtime.ChainHeight(), 1, 100)
}

// RevealAndDraw reveals the seed, verifies it against the commitment, and
// draws the winner deterministically from entries.
func RevealAndDraw(cur realm, salt []byte, seed []byte) {
	caller := assertUserCall(cur)
	if caller != admin {
		panic("raffle: admin only")
	}
	if status != StatusCommitted {
		panic("raffle: not in committed state")
	}
	if !commitreveal.VerifyReveal(commitment, salt, seed) {
		panic("raffle: reveal does not match commitment")
	}

	h := sha256.Sum256(seed)
	// Use the hash bytes as a big-endian number mod len(entries).
	var acc uint64
	for _, b := range h[:8] {
		acc = (acc << 8) | uint64(b)
	}
	winIdx := int64(acc % uint64(len(entries)))

	raw := entriesByIdx.Get(ufmt.Sprintf("%020d", winIdx))
	winnerEntry := raw.(*Entry)
	winner = winnerEntry.Player
	status = StatusRevealed
}

// PayoutWinner sends the pot to the drawn winner.
func PayoutWinner(cur realm) {
	assertUserCall(cur)
	if status != StatusRevealed {
		panic("raffle: winner not drawn yet")
	}

	realmAddr := cur.Address()
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	have := bk.GetCoins(realmAddr).AmountOf("ugnot")
	amount := pot
	if amount > have {
		amount = have
	}
	if amount <= 0 {
		panic("raffle: nothing to pay out")
	}
	bk.SendCoins(realmAddr, winner, chain.Coins{chain.NewCoin("ugnot", amount)})

	status = StatusClosed
}

// StartNewRound resets state for a fresh raffle after payout.
func StartNewRound(cur realm) {
	caller := assertUserCall(cur)
	if caller != admin {
		panic("raffle: admin only")
	}
	if status != StatusClosed {
		panic("raffle: current round not closed yet")
	}
	entries = []Entry{}
	entriesByIdx = avl.NewTree()
	status = StatusOpen
	commitment = nil
	winner = address("")
	pot = 0
}

func Render(path string) string {
	out := "# Raffle\n\n"
	out += ufmt.Sprintf("Status: %s | Entries: %d | Pot: %d ugnot\n",
		status.String(), len(entries), pot)
	if status == StatusRevealed || status == StatusClosed {
		out += ufmt.Sprintf("Winner: %s\n", winner)
	}
	return out
}

package auctionhouse

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

type AuctionStatus int

const (
	StatusActive AuctionStatus = iota
	StatusEnded
	StatusSettled
)

func (s AuctionStatus) String() string {
	switch s {
	case StatusActive:
		return "active"
	case StatusEnded:
		return "ended"
	case StatusSettled:
		return "settled"
	default:
		return "unknown"
	}
}

type Auction struct {
	ID           int64
	Seller       address
	ItemDesc     string
	MinBid       int64
	HighBid      int64
	HighBidder   address
	EndsAt       int64
	Status       AuctionStatus
	Refunds      *avl.Tree // addr -> int64 (outstanding refundable bids)
}

const auctionDurationBlocks int64 = 200

var (
	auctions *avl.Tree // id (string) -> *Auction
	nextID   int64
)

func init() {
	auctions = avl.NewTree()
	nextID = 1
}

func assertUserCall(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("auctionhouse: must be a direct user call")
	}
	return cur.Previous().Address()
}

func idKey(id int64) string {
	return ufmt.Sprintf("%020d", id)
}

func getAuction(id int64) *Auction {
	key := idKey(id)
	if !auctions.Has(key) {
		panic("auctionhouse: auction not found")
	}
	raw := auctions.Get(key)
	return raw.(*Auction)
}

// CreateAuction lists a new item for auction.
func CreateAuction(cur realm, itemDesc string, minBid int64) int64 {
	caller := assertUserCall(cur)
	if minBid <= 0 {
		panic("auctionhouse: minBid must be positive")
	}
	if itemDesc == "" {
		panic("auctionhouse: item description required")
	}

	id := nextID
	nextID++

	auctions.Set(idKey(id), &Auction{
		ID:       id,
		Seller:   caller,
		ItemDesc: itemDesc,
		MinBid:   minBid,
		EndsAt:   runtime.ChainHeight() + auctionDurationBlocks,
		Status:   StatusActive,
		Refunds:  avl.NewTree(),
	})
	return id
}

// Bid places a bid on an active auction. Outbid amounts become withdrawable refunds.
func Bid(cur realm, id int64) {
	caller := assertUserCall(cur)
	a := getAuction(id)
	if a.Status != StatusActive {
		panic("auctionhouse: auction is not active")
	}
	if runtime.ChainHeight() > a.EndsAt {
		panic("auctionhouse: auction time has expired, call EndAuction")
	}

	sent := unsafe.OriginSend()
	amount := sent.AmountOf("ugnot")

	minRequired := a.MinBid
	if a.HighBid > 0 {
		minRequired = a.HighBid + 1
	}
	if amount < minRequired {
		panic("auctionhouse: bid too low")
	}

	// Move previous high bid into refundable balance for previous bidder.
	if a.HighBid > 0 {
		prevKey := string(a.HighBidder)
		existing := int64(0)
		if a.Refunds.Has(prevKey) {
			existing = a.Refunds.Get(prevKey).(int64)
		}
		a.Refunds.Set(prevKey, existing+a.HighBid)
	}

	a.HighBid = amount
	a.HighBidder = caller
}

// WithdrawRefund lets an outbid bidder reclaim their funds.
func WithdrawRefund(cur realm, id int64) {
	caller := assertUserCall(cur)
	a := getAuction(id)

	key := string(caller)
	if !a.Refunds.Has(key) {
		panic("auctionhouse: no refund available")
	}
	amount := a.Refunds.Get(key).(int64)
	if amount <= 0 {
		panic("auctionhouse: no refund available")
	}
	a.Refunds.Set(key, int64(0))

	realmAddr := cur.Address()
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(realmAddr, caller, chain.Coins{chain.NewCoin("ugnot", amount)})
}

// EndAuction marks an expired auction as ended, ready for settlement.
func EndAuction(cur realm, id int64) {
	assertUserCall(cur)
	a := getAuction(id)
	if a.Status != StatusActive {
		panic("auctionhouse: auction is not active")
	}
	if runtime.ChainHeight() <= a.EndsAt {
		panic("auctionhouse: auction has not ended yet")
	}
	a.Status = StatusEnded
}

// Settle pays out the high bid to the seller.
func Settle(cur realm, id int64) {
	assertUserCall(cur)
	a := getAuction(id)
	if a.Status != StatusEnded {
		panic("auctionhouse: auction is not ended")
	}
	if a.HighBid <= 0 {
		a.Status = StatusSettled
		return
	}

	realmAddr := cur.Address()
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	have := bk.GetCoins(realmAddr).AmountOf("ugnot")
	amount := a.HighBid
	if amount > have {
		amount = have
	}
	bk.SendCoins(realmAddr, a.Seller, chain.Coins{chain.NewCoin("ugnot", amount)})

	a.Status = StatusSettled
}

func Render(path string) string {
	out := "# Auction House\n\n"
	out += ufmt.Sprintf("Total auctions: %d\n\n", auctions.Size())
	auctions.Iterate("", "", func(key string, value interface{}) bool {
		a := value.(*Auction)
		out += ufmt.Sprintf("## #%d: %s\n", a.ID, a.ItemDesc)
		out += ufmt.Sprintf("Status: %s | High bid: %d ugnot | Seller: %s\n\n",
			a.Status.String(), a.HighBid, a.Seller)
		return false
	})
	return out
}

package deadmanswitch

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Switch holds funds that release to a beneficiary if the owner fails to
// "check in" within the configured interval.
type Switch struct {
	ID            int64
	Owner         address
	Beneficiary   address
	Balance       int64
	CheckInBlocks int64
	LastCheckIn   int64
	Triggered     bool
}

var (
	switches *avl.Tree // id (string) -> *Switch
	nextID   int64
)

func init() {
	switches = avl.NewTree()
	nextID = 1
}

func assertUserCall(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("deadmanswitch: must be a direct user call")
	}
	return cur.Previous().Address()
}

func idKey(id int64) string {
	return ufmt.Sprintf("%020d", id)
}

func getSwitch(id int64) *Switch {
	key := idKey(id)
	if !switches.Has(key) {
		panic("deadmanswitch: switch not found")
	}
	raw := switches.Get(key)
	return raw.(*Switch)
}

// CreateSwitch funds a new dead-man's switch. checkInBlocks is the max
// number of blocks the owner can go without checking in before the
// beneficiary can claim the funds.
func CreateSwitch(cur realm, beneficiary address, checkInBlocks int64) int64 {
	caller := assertUserCall(cur)
	if checkInBlocks <= 0 {
		panic("deadmanswitch: checkInBlocks must be positive")
	}
	sent := unsafe.OriginSend()
	amount := sent.AmountOf("ugnot")
	if amount <= 0 {
		panic("deadmanswitch: must fund the switch with ugnot")
	}

	id := nextID
	nextID++

	switches.Set(idKey(id), &Switch{
		ID:            id,
		Owner:         caller,
		Beneficiary:   beneficiary,
		Balance:       amount,
		CheckInBlocks: checkInBlocks,
		LastCheckIn:   runtime.ChainHeight(),
		Triggered:     false,
	})
	return id
}

// CheckIn resets the timer, proving the owner is still active.
func CheckIn(cur realm, id int64) {
	caller := assertUserCall(cur)
	s := getSwitch(id)
	if caller != s.Owner {
		panic("deadmanswitch: only the owner can check in")
	}
	if s.Triggered {
		panic("deadmanswitch: switch already triggered")
	}
	s.LastCheckIn = runtime.ChainHeight()
}

// TopUp adds more funds to an existing switch.
func TopUp(cur realm, id int64) {
	assertUserCall(cur)
	s := getSwitch(id)
	if s.Triggered {
		panic("deadmanswitch: switch already triggered")
	}
	sent := unsafe.OriginSend()
	amount := sent.AmountOf("ugnot")
	if amount <= 0 {
		panic("deadmanswitch: must send ugnot to top up")
	}
	s.Balance += amount
}

// Claim lets the beneficiary withdraw funds once the check-in window has
// elapsed without a check-in.
func Claim(cur realm, id int64) {
	caller := assertUserCall(cur)
	s := getSwitch(id)
	if caller != s.Beneficiary {
		panic("deadmanswitch: only the beneficiary can claim")
	}
	if s.Triggered {
		panic("deadmanswitch: already claimed")
	}
	elapsed := runtime.ChainHeight() - s.LastCheckIn
	if elapsed < s.CheckInBlocks {
		panic("deadmanswitch: check-in window has not elapsed yet")
	}

	realmAddr := cur.Address()
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	have := bk.GetCoins(realmAddr).AmountOf("ugnot")
	amount := s.Balance
	if amount > have {
		amount = have
	}
	if amount > 0 {
		bk.SendCoins(realmAddr, s.Beneficiary, chain.Coins{chain.NewCoin("ugnot", amount)})
	}

	s.Balance = 0
	s.Triggered = true
}

// CancelSwitch lets the owner reclaim funds and deactivate the switch
// at any time before it is triggered.
func CancelSwitch(cur realm, id int64) {
	caller := assertUserCall(cur)
	s := getSwitch(id)
	if caller != s.Owner {
		panic("deadmanswitch: only the owner can cancel")
	}
	if s.Triggered {
		panic("deadmanswitch: already triggered")
	}

	realmAddr := cur.Address()
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	have := bk.GetCoins(realmAddr).AmountOf("ugnot")
	amount := s.Balance
	if amount > have {
		amount = have
	}
	if amount > 0 {
		bk.SendCoins(realmAddr, s.Owner, chain.Coins{chain.NewCoin("ugnot", amount)})
	}

	s.Balance = 0
	s.Triggered = true
}

func Render(path string) string {
	out := "# Dead Man's Switch\n\n"
	out += ufmt.Sprintf("Total switches: %d\n\n", switches.Size())
	switches.Iterate("", "", func(key string, value interface{}) bool {
		s := value.(*Switch)
		out += ufmt.Sprintf("## #%d\n", s.ID)
		out += ufmt.Sprintf("Owner: %s | Beneficiary: %s | Balance: %d ugnot | Triggered: %t\n\n",
			s.Owner, s.Beneficiary, s.Balance, s.Triggered)
		return false
	})
	return out
}
